const API_BASE = import.meta.env.VITE_API_BASE_URL || 'http://localhost:8000';
const WS_BASE = import.meta.env.VITE_WS_BASE_URL || 'ws://localhost:8000';

function snakeToCamel<T>(obj: Record<string, unknown>): T {
  const result: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(obj)) {
    const camelKey = key.replace(/_([a-z])/g, (_, letter) => letter.toUpperCase());
    result[camelKey] = value;
  }
  return result as T;
}

function camelToSnake(obj: Partial<CalibrationSettings>): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(obj)) {
    const snakeKey = key.replace(/[A-Z]/g, (letter) => `_${letter.toLowerCase()}`);
    result[snakeKey] = value;
  }
  return result;
}

export async function getState(): Promise<QuantumState> {
  const response = await fetch(`${API_BASE}/api/state`);
  if (!response.ok) {
    throw new Error(`Failed to fetch state: ${response.statusText}`);
  }
  const data = await response.json();
  return snakeToCamel<QuantumState>(data);
}

export async function updateCalibration(
  settings: Partial<CalibrationSettings>
): Promise<{ state: QuantumState; calibration: CalibrationSettings }> {
  const response = await fetch(`${API_BASE}/api/calibration`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(camelToSnake(settings)),
  });
  if (!response.ok) {
    throw new Error(`Failed to update calibration: ${response.statusText}`);
  }
  const data = await response.json();
  return {
    state: snakeToCamel<QuantumState>(data.state),
    calibration: snakeToCamel<CalibrationSettings>(data.calibration),
  };
}

export async function recalibrate(): Promise<QuantumState> {
  const response = await fetch(`${API_BASE}/api/recalibrate`, { method: 'POST' });
  if (!response.ok) {
    throw new Error(`Failed to recalibrate: ${response.statusText}`);
  }
  const data = await response.json();
  return snakeToCamel<QuantumState>(data.state);
}

export async function getSecurityAudit(): Promise<SecurityAudit> {
  const response = await fetch(`${API_BASE}/api/security/audit`);
  if (!response.ok) {
    throw new Error(`Failed to fetch security audit: ${response.statusText}`);
  }
  const data = await response.json();

  const threats: ThreatVector[] = (data.threats || []).map((t: Record<string, unknown>) => ({
    id: String(t.threat_id || t.id || ''),
    name: String(t.name || ''),
    severity: (t.severity as ThreatVector['severity']) || 'MEDIUM',
    description: String(t.description || ''),
    mitigation: String(t.mitigation || ''),
  }));

  return {
    overallScore: data.overall_score ?? 0,
    state: (data.security_state as SecurityAudit['state']) || 'CRITICAL',
    antiAttackConfidence: data.anti_attack_confidence ?? 0,
    threats,
    lastAudit: new Date(data.timestamp || Date.now()),
  };
}

export async function getTelemetry(limit = 50): Promise<TelemetryData[]> {
  const response = await fetch(`${API_BASE}/api/telemetry?limit=${limit}`);
  if (!response.ok) {
    throw new Error(`Failed to fetch telemetry: ${response.statusText}`);
  }
  const data = await response.json();
  return data.map((point: Record<string, unknown>) => snakeToCamel<TelemetryData>(point));
}

export function connectTelemetry(
  onData: (data: TelemetryData) => void,
  onError?: (error: Event) => void
): () => void {
  const ws = new WebSocket(`${WS_BASE}/ws/telemetry`);

  ws.onmessage = (event) => {
    try {
      const parsed = JSON.parse(event.data);
      onData(snakeToCamel<TelemetryData>(parsed));
    } catch (err) {
      console.error('Failed to parse telemetry message:', err);
    }
  };

  ws.onerror = (error) => {
    console.error('Telemetry WebSocket error:', error);
    onError?.(error);
  };

