def repository_checks(self) -> list[tuple[str, str]]:
    checks: list[tuple[str, str]] = []
    vault = self.load_vault_config()
    agents = self.load_agents()
    models = self.model_files()
    runnable_models = self.llama_cpp_model_files()
    serialized_models = self.serialized_model_files()
    model_artifacts = self.model_artifacts()
    configured_model_path = self.configured_model_path()

    missing_directories = [
        directory_name
        for directory_name in vault.structure
        if not (self.root / directory_name).exists()
    ]
    if missing_directories:
        missing_directory_message = ", ".join(missing_directories)
        checks.append(
            (
                "warning",
                "Configured directories missing from workspace: "
                + missing_directory_message,
            )
        )

    if agents:
        checks.append(("ok", f"Detected {len(agents)} agent DNA file(s)."))
    else:
        checks.append(("warning", "No agent DNA files were found."))

    if models:
        detail = f"Detected {len(models)} persisted model artifact(s) in Models/."
        if runnable_models:
            detail += f" Runnable GGUF models: {len(runnable_models)}."
        if serialized_models:
            detail += f" Serialized exports: {len(serialized_models)}."
        checks.append(("ok", detail))
    else:
        warning_detail = "No persisted model artifacts found in Models/."
        unsupported_artifacts = [
            path.name
            for path in model_artifacts
            if path.suffix != ".gguf"
            and path.suffix != ".pkl"
            and not path.name.endswith(".json.gz")
        ]
        if unsupported_artifacts:
            warning_detail += " Unsupported artifact(s) present: " + ", ".join(
                unsupported_artifacts
            )
        checks.append(("warning", warning_detail))

    if configured_model_path is not None and not configured_model_path.exists():
        checks.append(
            (
                "warning",
                "Configured llama.cpp model path is missing: "
                + str(configured_model_path.relative_to(self.root)),
            )
        )
    elif configured_model_path is not None:
        configured_name = configured_model_path.name
        checks.append(
            (
                "ok",
                "Configured llama.cpp model path exists: " + configured_name,
            )
        )

    if (self.root / ".venv").exists():
        checks.append(("ok", "Local virtual environment .venv is present."))
    else:
        checks.append(("warning", "Local virtual environment .venv is missing."))

    return checks

def find_agent(self, name: str) -> tuple[Path, AgentDNA] | None:
    needle = name.casefold()
    for path, agent in self.load_agents():
        if needle in {
            agent.metatron_agent.casefold(),
            agent.dna_agent_name.casefold(),
        }:
            return path, agent
    return None

    for path in sorted(self.root.glob("Agent_*/conscious_dna.json")):
        validations.append(self._validate_file(path, AgentDNA))

    for path in sorted(self.root.glob("*/*_memory.json")):
        validations.append(self._validate_file(path, AgentMemory))

    return validations

def _validate_optimization_log(self) -> ValidationResult:
    path = self.root / "optimization_log.json"
    if not path.exists():
        return ValidationResult(
            path=str(path.relative_to(self.root)),
            model_name="OptimizationEntry[]",
            valid=False,
            error="File not found",
        )

    try:
        payload = self._load_json(path)
        for item in payload:
            OptimizationEntry.model_validate(item)
        return ValidationResult(
            path=str(path.relative_to(self.root)),
            model_name="OptimizationEntry[]",
            valid=True,
        )
    except (ValidationError, ValueError, TypeError) as exc:
        return ValidationResult(
            path=str(path.relative_to(self.root)),
            model_name="OptimizationEntry[]",
            valid=False,
            error=str(exc),
        )

def _validate_file(
    self,
    path: Path,
    schema: (
        type[VaultConfig]
        | type[GeometryConfig]
        | type[AgentDNA]
        | type[AgentMemory]
    ),
) -> ValidationResult:
    if not path.exists():
        return ValidationResult(
            path=str(path.relative_to(self.root)),
            model_name=schema.__name__,
            valid=False,
            error="File not found",
        )

    try:
        schema.model_validate(self._load_json(path))
        return ValidationResult(
            path=str(path.relative_to(self.root)),
            model_name=schema.__name__,
            valid=True,
        )
    except (ValidationError, ValueError, TypeError) as exc:
        return ValidationResult(
            path=str(path.relative_to(self.root)),
            model_name=schema.__name__,
            valid=False,
            error=str(exc),
        )

def validate_repository(self) -> list[ValidationResult]:
    validations: list[ValidationResult] = []
    validations.append(
        self._validate_file(self.root / "vault_config.json", VaultConfig)
    )
    validations.append(
        self._validate_file(
            self.root / "metatron_geometry.json",
            GeometryConfig,
        )
    )
    validations.append(self._validate_optimization_log())

