import { lazy, Suspense, useEffect, useState } from 'react'

// Available molecules for VQE
const MOLECULES = [
  { id: 'H2', name: 'H₂ (Hydrogen)', formula: 'H₂', description: 'Dihydrogen at equilibrium (0.735 Å)' },
  { id: 'LiH', name: 'LiH (Lithium Hydride)', formula: 'LiH', description: 'Lithium hydride at equilibrium (1.595 Å)' },
  { id: 'HeH+', name: 'HeH⁺ (Helium Hydride Ion)', formula: 'HeH⁺', description: 'Helium hydride ion (1.463 Å)' },
  { id: 'BeH2', name: 'BeH₂ (Beryllium Hydride)', formula: 'BeH₂', description: 'Beryllium hydride linear geometry' },
  { id: 'H2O', name: 'H₂O (Water)', formula: 'H₂O', description: 'Water molecule at equilibrium geometry' },
]

// Execution modes
type ExecutionMode = 'simulator' | 'noisy_simulator' | 'hardware'

interface NoiseProfile {
  name: string
  num_qubits: number
  avg_t1_us: number
  avg_t2_us: number
  avg_readout_error: number
}

interface EnergyPoint {
  iteration: number
  energy: number
}

const VQEEnergyChart = lazy(() => import('./VQEEnergyChart'))

export default function VQEView() {
  const [loading, setLoading] = useState(false)
  const [result, setResult] = useState<any>(null)
  const [error, setError] = useState('')
  const [selectedMolecule, setSelectedMolecule] = useState('H2')
  const [executionMode, setExecutionMode] = useState<ExecutionMode>('simulator')
  const [noiseProfiles, setNoiseProfiles] = useState<string[]>([])
  const [selectedNoiseProfile, setSelectedNoiseProfile] = useState<string>('')
  const [profileInfo, setProfileInfo] = useState<Record<string, NoiseProfile>>({})
  const [hardwareStatus, setHardwareStatus] = useState<string | null>(null)

  const energies: EnergyPoint[] = Array.isArray(result?.energies) ? result.energies : []

  // Fetch available noise profiles on mount
  useEffect(() => {
    const fetchNoiseProfiles = async () => {
      try {
        const res = await fetch('/noise/profiles')
        const data = await res.json()
        if (data.profiles && data.profiles.length > 0) {
          setNoiseProfiles(data.profiles)
          setSelectedNoiseProfile(data.profiles[0])
          if (data.profile_info) {
            setProfileInfo(data.profile_info)
          }
        }
      } catch (err) {
        console.error('Failed to fetch noise profiles:', err)
      }
    }
    fetchNoiseProfiles()
  }, [])

  const runVQE = async () => {
    setLoading(true)
    setError('')
    setResult(null)
    setHardwareStatus(null)

    try {
      const params = new URLSearchParams({
        molecule: selectedMolecule,
        use_hardware: (executionMode === 'hardware').toString(),
        use_noisy_simulator: (executionMode === 'noisy_simulator').toString(),
        noise_profile: selectedNoiseProfile,
        max_iters: '50',
      })

      const res = await fetch(`/vqe?${params}`)
      const data = await res.json()

      if (data.error) {
        setError(data.error)
      } else {
        setResult(data)
        if (data.hardware_used) {
          setHardwareStatus(`Executed on ${data.backend_name || 'IBM Quantum hardware'} (Job: ${data.job_id || 'N/A'})`)
        } else if (data.noisy_simulator_used) {
          const info = data.profile_info || {}
          setHardwareStatus(`Simulated with ${data.noise_profile || 'unknown'} noise profile (${info.num_qubits || '?'} qubits, avg T1: ${info.avg_t1_us || '?'} μs)`)
        }
      }
    } catch (error) {
      console.error('Error:', error)
      setError('Failed to connect to backend')
    } finally {
      setLoading(false)
    }
  }

