        """Raise the grid operator to a power."""
        if self == self.from_string("I") or n == 0:  # Identity:
            return GridOp((1, 0), (0, 0), (0, 0), (1, 0))
        if self == self.from_string("A"):  # A
            return GridOp((1, 0), (-2 * n, 0), (0, 0), (1, 0))
        if self == self.from_string("B"):  # B
